/* Moving Command Center — offline shell. Generated by build.sh. Do not hand-edit. */
const CACHE = "mcc-v444";
const SHELL = ["./", "./index.html", "./app.js", "./manifest.webmanifest",
  "./icon.svg", "./icon-192.png", "./icon-512.png", "./icon-180.png", "./icon-maskable.png", "./fonts/atkinson-next.woff",
  "./calm/walk.webp", "./calm/walk-end.jpg", "./calm/peek.png", "./calm/monocle-still.webp",
  "./start/", "./start/index.html", "./start/thread.html", "./start/wordmark-green.png", "./start/wordmark-cream.png",
  "./start/rabbit-walks-in.webp", "./start/rabbit-walks-in-end.jpg", "./start/rabbit-walks-in-room.jpg", "./start/wordmark-ears.png", "./start/wordmark-ears-cream.png",
  "./start/tab1.mp3", "./start/tab2.mp3", "./start/tab3.mp3", "./start/tab4.mp3"];

self.addEventListener("message", (e) => {
  if (e.data === "skip-waiting") self.skipWaiting();
});

/* chat tester, 9 Nov: the walk wouldn't load in one browser (net::ERR_FAILED). All-or-nothing caching meant one
   file that couldn't be fetched (a sound, say) stopped every new version from installing, leaving an older worker in
   charge for good. Each file is saved on its own now, so a new version always takes over.
   break panel, 24 Nov: each file is fetched past the browser's own cache (cache: "reload"), so a new version never
   stores yesterday's app.js under today's name. */
self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => Promise.all(SHELL.map((u) => c.add(new Request(u, { cache: "reload" })).catch(() => {})))).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  e.respondWith(
    /* alpha test, 8 Nov: with no signal the app wouldn't open. The copy for the cache was made after the page had
       started reading the response, so it failed and nothing new was ever saved; and start/?home didn't match the
       saved start/. The copy is made first now, a saved page matches whatever follows the "?", and a page that
       can't be reached falls back to its own part of the app. */
    /* beta tester (Reddit), 20 Nov 2026: "Pack my first box" showed a browser error every time. The host sends
       thread.html on to thread, and a page handed over by a worker after a redirect is refused by the browser
       when it opens a page. Every answer is now handed over clean, so the page opens. */
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      const live = fetch(req)
        .then((res) => {
          if (res && res.ok) { const copy = res.clone(); clean(copy).then((ok) => caches.open(CACHE).then((c) => c.put(req, ok))).catch(() => {}); }
          return clean(res);
        })
        .catch(() => hit ? clean(hit) : caches.match(new URL(req.url).pathname.indexOf("/start/") >= 0 ? "./start/" : "./").then(clean));
      return hit ? clean(hit) : live;
    })
  );
});

function clean(res) {
  if (!res || !res.redirected) return Promise.resolve(res);
  return res.blob().then((b) => new Response(b, { status: res.status, statusText: res.statusText, headers: res.headers }));
}
